function el(id){return document.getElementById(id)}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const t=el('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(t._x);t._x=setTimeout(()=>t.classList.add('hidden'),3200)}
function formatDuration(sec=0){sec=Math.max(0,Number(sec)||0);return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')}
function formatDue(v){if(!v)return'No deadline';return' Due '+new Date(v+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}
function initials(name=''){return name.split(/\s+/).filter(Boolean).map(n=>n[0]).join('').slice(0,2).toUpperCase()||'?'}
function assignmentIcon(k){return SCENARIOS[k]?.icon||({demo:'💡',close:'🤝',product:'📦'})[k]||'📝'}

async function callAI(type,payload){const {data}=await SB.auth.getSession();const token=data?.session?.access_token;if(!token)throw new Error('Please sign in again.');const r=await fetch(EFURL,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({type,payload})});const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'AI request failed');return d}

