function renderNav(active){const host=el('nav-tabs');host.innerHTML='';if(!APP.user)return;const student=[['student-home','Home'],['practice-page','Practice'],['assignments-page','Assignments'],['performance-page','Performance'],['showdown-page','Showdown'],['playbook-page','Playbook']];const teacher=[['teacher-home','Dashboard'],['teacher-assign','Assignments'],['grade-review','Grade Review'],['showdown-page','Showdown']];(APP.role==='teacher'?teacher:student).forEach(([id,label])=>{const b=document.createElement('button');b.className='nav-tab'+(active===id?' active':'');b.textContent=label;b.onclick=()=>showPage(id);host.appendChild(b)});const out=document.createElement('button');out.className='nav-tab';out.textContent='Log out';out.onclick=logout;host.appendChild(out)}
