async function loadStudentHome(){if(!APP.user)return;el('student-name').textContent=(APP.profile?.full_name||'Student').split(' ')[0];const [sr,ar]=await Promise.all([SB.from('sessions').select('overall_score,duration_seconds,created_at').eq('student_id',APP.user.id).order('created_at',{ascending:false}),SB.from('assignments').select('*').eq('active',true).order('due_date',{ascending:true}).limit(2)]);const sessions=sr.data||[],scores=sessions.map(s=>Number(s.overall_score)).filter(Number.isFinite);el('home-best').textContent=scores.length?Math.max(...scores):'—';el('home-attempts').textContent=sessions.length;el('home-time').textContent=formatMinutes(sessions.reduce((n,s)=>n+(s.duration_seconds||0),0));renderAssignments(ar.data||[],el('home-assignments'),sessions,true);const next=el('next-step');if((ar.data||[]).length)next.innerHTML='<strong>Your next required step:</strong> '+escapeHtml(ar.data[0].title||SCENARIOS[ar.data[0].scenario]?.name||'Sales Lab assignment')+'.';else next.innerHTML='<strong>Week 1 focus:</strong> Complete an ungraded Elevator Pitch baseline, review the feedback, and identify one improvement goal.'}
function formatMinutes(sec){sec=Number(sec)||0;return sec>=3600?Math.floor(sec/3600)+'h '+Math.floor(sec%3600/60)+'m':Math.floor(sec/60)+'m'}
function startFreePractice(scenario){APP.activeAssignment=null;APP.activeCompetitionRound=null;if(scenario)APP.selectedScenario=scenario;selectPracticeCard(APP.selectedScenario);showPage('practice-page')}

