function beginPractice(){if(APP.selectedScenario==='interview')APP.selectedBuyer='sandra';resetSession();const s=SCENARIOS[APP.selectedScenario],b=BUYERS[APP.selectedBuyer],showdown=!!APP.activeCompetitionRound;el('arena-buyer-img').src=b.photo;el('arena-buyer-name').textContent=b.name;el('arena-buyer-role').textContent=b.role;el('arena-scenario').textContent=s.icon+' '+s.name;el('arena-context').textContent=CONTEXTS[el('context-select').value];const box=el('chat-input');if(box){box.readOnly=showdown;box.placeholder=showdown?'Use the microphone to speak your official Showdown response':'Type or use the microphone…'}showPage('arena-page');APP.startedAt=Date.now();APP.timer=setInterval(updateTimer,1000);if(APP.activeAssignment||APP.activeCompetitionRound)startAssignmentRecording().then(ok=>{if(ok)seedOpening();else{resetSession();showPage('practice-page');toast(showdown?'Showdown recording was not started. No official attempt was used.':'Assignment recording was not started.')}});else seedOpening()}
function resetSession(){stopAudio();if(APP.timer)clearInterval(APP.timer);Object.assign(APP,{history:[],transcript:[],scores:{},fillers:{um:0,like:0,youknow:0,so:0,basically:0},lastFeedback:'',interviewFeedback:[],startedAt:null});el('chat').innerHTML='';SKILLS.forEach(k=>setSkill(k,null));el('overall-score').textContent='—';el('session-time').textContent='0:00';el('session-turns').textContent='0';el('voice-status').textContent='';APP.recordedVoice=false;APP.pendingVoiceTranscript=false;APP.audioChunks=[]}
